package com.bank.jvm.monitor;

import java.util.logging.Logger;

public class MonitoringDemoService {
    private static final Logger log = Logger.getLogger(MonitoringDemoService.class.getName());

    public static void main(String[] args) throws InterruptedException {
        boolean leak = args.length > 0 && args[0].equals("--leak");
        log.info("Bank: National Bank of India — JVM monitoring demo (leak=" + leak + ")");

        JvmMetricsExporter exporter = new JvmMetricsExporter();
        LeakyCache cache = new LeakyCache();

        for (int cycle = 0; cycle < 10; cycle++) {
            // Simulate request processing that allocates transient objects.
            for (int i = 0; i < 200_000; i++) {
                byte[] transient_ = new byte[256]; // dies quickly
                transient_[0] = (byte) i;
                if (leak) cache.remember("TXN-" + cycle + "-" + i, transient_); // never evicts!
            }
            System.gc(); // force a collection so the "after GC" floor is meaningful in the demo
            exporter.exportAlertableMetrics(cycle);
            Thread.sleep(300);
        }

        if (leak) {
            log.severe(() -> "Leak mode: used-heap-after-GC floor kept RISING — "
                    + "this is what the monotonic-growth alert catches");
        } else {
            log.info("Healthy mode: used-heap-after-GC floor stayed flat");
        }
    }
}

// ─── Would be in LeakyCache.java in a real project ───
class LeakyCache {
    private final java.util.Map<String, byte[]> store = new java.util.HashMap<>();
    void remember(String key, byte[] value) { store.put(key, value); } // no eviction = leak
    int size() { return store.size(); }
}
