package com.bank.jvm.monitor;

import java.lang.management.GarbageCollectorMXBean;
import java.lang.management.ManagementFactory;
import java.lang.management.MemoryPoolMXBean;
import java.util.logging.Logger;

class JvmMetricsExporter {
    private static final Logger log = Logger.getLogger(JvmMetricsExporter.class.getName());

    // Emits the four metrics worth ALERTING on.
    void exportAlertableMetrics(int cycle) {
        // 1) Old-gen occupancy %
        double oldGenPct = oldGenOccupancyPercent();
        // 2) + 3) total GC time (basis for GC-time ratio and pause tracking)
        long totalGcMs = totalGcTimeMs();
        // 4) used heap AFTER gc — the monotonic-growth floor
        long usedAfterGcMb = ManagementFactory.getMemoryMXBean()
                .getHeapMemoryUsage().getUsed() / (1024 * 1024);

        log.info(() -> String.format(
            "cycle=%d | oldGen=%.1f%% | totalGcMs=%d | usedHeapAfterGC=%dMB",
            cycle, oldGenPct, totalGcMs, usedAfterGcMb));

        if (oldGenPct > 80.0) {
            log.warning(() -> "ALERT: old-gen occupancy " + String.format("%.1f", oldGenPct)
                    + "% > 80% after GC — live set large or leaking");
        }
    }

    private double oldGenOccupancyPercent() {
        for (MemoryPoolMXBean pool : ManagementFactory.getMemoryPoolMXBeans()) {
            String n = pool.getName().toLowerCase();
            if (n.contains("old") || n.contains("tenured")) {
                long used = pool.getUsage().getUsed();
                long max = pool.getUsage().getMax();
                if (max > 0) return 100.0 * used / max;
            }
        }
        return 0.0;
    }

    private long totalGcTimeMs() {
        long total = 0;
        for (GarbageCollectorMXBean gc : ManagementFactory.getGarbageCollectorMXBeans()) {
            total += Math.max(gc.getCollectionTime(), 0);
        }
        return total;
    }
}
